add_expense:
def add_expense(state, amount, category) do
  add_expense(state, amount, category, :none)
end
def add_expense(state, amount, category, note) do
  if not (is_number(amount) and amount > 0), do: raise("amount must be greater than zero")
  if not (is_binary(category) and category != ""), do: raise("category is required")
  if note != :none and not is_binary(note), do: raise("breaks expenses-shape")
  expenses = Map.get(state, "expenses", [])
  id = length(expenses) + 1
  expense =
    case note do
      :none -> %{"amount" => amount, "category" => category}
      n -> %{"amount" => amount, "category" => category, "note" => n}
    end
  {id, Map.put(state, "expenses", expenses ++ [expense])}
end

set_budget:
def set_budget(state, category, amount) do
  if not (is_binary(category) and category != ""), do: raise("category is required")
  if not (is_number(amount) and amount > 0), do: raise("amount must be greater than zero")
  budgets = Map.get(state, "budgets", %{})
  {amount, Map.put(state, "budgets", Map.put(budgets, category, amount))}
end
